            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(3, 9, 4);
        List<Double> doubles = List.of(2.5, 7.5, 5.0);
        List<Long> longs = List.of(1L, 2L, 4L);

        check("spread(List.of(3, 9, 4))", 6.0, NumericRangeSummary.spread(ints));
        check("spread(List.of(2.5, 7.5, 5.0))", 5.0, NumericRangeSummary.spread(doubles));
        check("spread(empty)", 0.0, NumericRangeSummary.spread(new java.util.ArrayList<Integer>()));
        check("spread(single)", 0.0, NumericRangeSummary.spread(List.of(42)));
