import java.util.List;

public class NumericRangeSummary {

    public static <T extends Number & Comparable<T>> double spread(List<T> values) {
        if (values.isEmpty()) {
            return 0.0;
        }
        T smallest = values.get(0);
        T largest = values.get(0);
        for (T value : values) {
            if (value.compareTo(smallest) < 0) {
                smallest = value;
            }
            if (value.compareTo(largest) > 0) {
                largest = value;
            }
        }
        return largest.doubleValue() - smallest.doubleValue();
    }

    public static <T extends Number & Comparable<T>> double average(List<T> values) {
        if (values.isEmpty()) {
            return 0.0;
        }
        double total = 0.0;
        for (T value : values) {
            total += value.doubleValue();
        }
        double mean = total / values.size();
        return Math.round(mean * 100.0) / 100.0;
    }

    public static <T extends Number & Comparable<T>> int aboveAverage(List<T> values) {
        if (values.isEmpty()) {
            return 0;
        }
        double total = 0.0;
        for (T value : values) {
            total += value.doubleValue();
        }
        double mean = total / values.size();
        int count = 0;
        for (T value : values) {
            if (value.doubleValue() > mean) {
                count++;
            }
        }
        return count;
    }
}
